// v23.xx (gfx31), HIS ORDER 2026-10-12 (the graphics program, item 13): MACHINES DIE IN A BLAST. A machine killed left only the
// v17.47 silhouette that turns and fades, and a puff. gfxOnDeath (the gfx2 hook in deathAnimAdd, which runs in every window that
// shows the death, never in a bot raid) now sets off the explosion module at the size of what died (BOOMK): a Crawler 0.6, a Snitch
// 0.5, a Sentry or a Howler 1, a Warden 1.8 with two smaller secondary pops after it. People (pillagers, the Stray) do not explode.
// A blast is only set off where the player can see the body die (canSee, the same eyes VIS uses), so a fireball never marks a kill
// behind a wall through the fog of war.
var BOOMK={crawler:0.6,snitch:0.5,listener:0.8,peddler:0.8,sentry:1,howler:1,choir:1.2,bulwark:1.3,warden:1.8};
function gfxOnDeath(a){
  if(!gfxHook('death')) return false;
  if(!a||!a.kind||!(BOOMK[a.kind]>0)) return false;
  var p=G.player, s=BOOMK[a.kind];
  if(!p||!isFinite(+a.x)||!isFinite(+a.y)) return false;
  if(G.vseg&&!canSee(p.x,p.y,p.face,a.x,a.y,G.vseg)) return false;
  boomFx(a.x,a.y,s,a.kind);
  if(a.kind==='warden'){
    if(boomFx(a.x+fxn(-34,34),a.y+fxn(-22,22),0.7,'pop')) BOOMS[BOOMS.length-1].t0+=0.28;
    if(boomFx(a.x+fxn(-34,34),a.y+fxn(-22,22),0.6,'pop')) BOOMS[BOOMS.length-1].t0+=0.55;
  }
  return true;
}
// ===== GFX-E end =====

